Term:
Inductive Term =
  tArithBin {ArithOp, Term, Term}
| tBoolBin {BoolOp, Term, Term}
| tArithUn {ArithOp, Term}
| tBoolUn {BoolOp, Term}
| tVar Int | tCInt Int | tCBool Bool;

Term2:
Inductive Term2 =
  bin {Op, Term2, Term2}
| un {Op, Term2}
| var Int | cInt Int | cBool Bool;

